# Embedded responsive Tailwind CSS web interface for Braille Digitizer
HTML_CONTENT = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Braille Digitizer — Shadow-Assisted OBR System</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">\n  <style>\n    .dragover { border-color: #3b82f6 !important; background-color: #eff6ff !important; }\n  </style>\n</head>\n<body class="bg-slate-50 text-slate-800 font-sans min-h-screen flex flex-col">\n\n  <!-- Header -->\n  <header class="bg-white border-b border-slate-200 sticky top-0 z-50">\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex flex-col sm:flex-row items-center justify-between gap-4">\n      <div class="flex items-center gap-3">\n        <div class="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center text-white text-xl shadow-md">\n          <i class="fa-solid fa-braille"></i>\n        </div>\n        <div>\n          <h1 class="text-xl font-bold text-slate-900 leading-tight">BRAILLE DIGITIZER</h1>\n          <p class="text-xs text-slate-500 font-medium">Shadow-Assisted Optical Braille Recognition (OBR) System</p>\n        </div>\n      </div>\n\n      <!-- Navigation Tabs -->\n      <div class="flex bg-slate-100 p-1 rounded-xl">\n        <button id="tab-recognize" onclick="switchTab(\'recognize\')" class="px-4 py-2 text-sm font-semibold rounded-lg bg-white shadow-sm text-blue-600 transition">\n          <i class="fa-solid fa-camera mr-2"></i>Recognize Braille\n        </button>\n        <button id="tab-generate" onclick="switchTab(\'generate\')" class="px-4 py-2 text-sm font-semibold rounded-lg text-slate-600 hover:text-slate-900 transition">\n          <i class="fa-solid fa-pen-nib mr-2"></i>Generate Braille\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- Main Container -->\n  <main class="flex-grow max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">\n\n    <!-- TAB 1: RECOGNIZE BRAILLE -->\n    <section id="panel-recognize" class="space-y-8">\n\n      <!-- Upload Zone -->\n      <div class="bg-white rounded-2xl border-2 border-dashed border-slate-300 p-8 text-center hover:border-blue-500 transition cursor-pointer relative" id="drop-zone" onclick="document.getElementById(\'file-input\').click()">\n        <input type="file" id="file-input" class="hidden" accept="image/*" onchange="handleFileSelect(event)">\n        <div class="flex flex-col items-center justify-center gap-3">\n          <div class="w-14 h-14 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center text-2xl">\n            <i class="fa-solid fa-cloud-arrow-up"></i>\n          </div>\n          <div>\n            <span class="font-semibold text-slate-900">Click to upload</span> or drag and drop a Braille page image\n            <p class="text-xs text-slate-500 mt-1">Supports PNG, JPG, JPEG, BMP (Photographed with side-lighting or scanned)</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- Quick Samples -->\n      <div class="flex flex-wrap items-center justify-center gap-2 pt-1">\n        <span class="text-xs text-slate-400 font-medium mr-1"><i class="fa-solid fa-bolt text-amber-500 mr-1"></i>Try Instant Sample:</span>\n        <button onclick="loadSample(\'hello world\\nbraille digitizer\')" class="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-semibold text-slate-700 hover:border-blue-400 hover:text-blue-600 transition shadow-xs">Sample 1: \'Hello World\'</button>\n        <button onclick="loadSample(\'the quick brown fox\\njumps over the lazy dog\')" class="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-semibold text-slate-700 hover:border-blue-400 hover:text-blue-600 transition shadow-xs">Sample 2: Pangram</button>\n        <button onclick="loadSample(\'123 456 789\\nbraille 2026\')" class="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-semibold text-slate-700 hover:border-blue-400 hover:text-blue-600 transition shadow-xs">Sample 3: Numbers & Text</button>\n      </div>\n\n      <!-- Processing Status -->\n      <div id="status-card" class="hidden bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-center justify-between text-blue-900 text-sm">\n        <div class="flex items-center gap-3">\n          <div id="status-spinner" class="animate-spin text-blue-600 text-lg">\n            <i class="fa-solid fa-circle-notch"></i>\n          </div>\n          <span id="status-text" class="font-medium">Processing shadow map and reconstructing grid lattice...</span>\n        </div>\n        <div id="stats-badges" class="hidden flex gap-2">\n          <span id="badge-dots" class="px-2.5 py-1 bg-white rounded-full text-xs font-semibold text-blue-700 shadow-sm border border-blue-100"></span>\n          <span id="badge-cells" class="px-2.5 py-1 bg-white rounded-full text-xs font-semibold text-emerald-700 shadow-sm border border-emerald-100"></span>\n        </div>\n      </div>\n\n      <!-- Results Grid -->\n      <div id="results-container" class="hidden space-y-6">\n        <div class="grid grid-cols-1 lg:grid-cols-2 gap-6">\n\n          <!-- Left: Visual Canvas / Lattice -->\n          <div class="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm space-y-3">\n            <div class="flex items-center justify-between border-b border-slate-100 pb-3">\n              <h3 class="font-bold text-slate-900 text-sm flex items-center gap-2">\n                <i class="fa-solid fa-microscope text-blue-600"></i>Reconstructed 2×3 Grid Lattice\n              </h3>\n              <span class="text-xs text-slate-500 font-medium">Green: Centroids | Blue: Cells</span>\n            </div>\n            <div class="w-full bg-slate-950 rounded-xl overflow-hidden flex items-center justify-center min-h-[340px]">\n              <img id="overlay-img" class="max-h-[500px] w-auto object-contain" alt="Lattice Overlay">\n            </div>\n          </div>\n\n          <!-- Right: Decoded Bilingual Text -->\n          <div class="space-y-6 flex flex-col">\n\n            <!-- English Text -->\n            <div class="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm space-y-3 flex-1 flex flex-col">\n              <div class="flex items-center justify-between border-b border-slate-100 pb-3">\n                <h3 class="font-bold text-slate-900 text-sm flex items-center gap-2">\n                  <i class="fa-solid fa-font text-blue-600"></i>Translated English (UEB)\n                </h3>\n                <button onclick="copyText(\'english-text\')" class="text-xs text-blue-600 font-semibold hover:text-blue-800 flex items-center gap-1">\n                  <i class="fa-regular fa-copy"></i>Copy\n                </button>\n              </div>\n              <textarea id="english-text" readonly class="flex-grow w-full bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm font-mono text-slate-800 focus:outline-none resize-none min-h-[140px]"></textarea>\n            </div>\n\n            <!-- Russian Text -->\n            <div class="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm space-y-3 flex-1 flex flex-col">\n              <div class="flex items-center justify-between border-b border-slate-100 pb-3">\n                <h3 class="font-bold text-slate-900 text-sm flex items-center gap-2">\n                  <i class="fa-solid fa-language text-purple-600"></i>Translated Russian Braille\n                </h3>\n                <button onclick="copyText(\'russian-text\')" class="text-xs text-purple-600 font-semibold hover:text-purple-800 flex items-center gap-1">\n                  <i class="fa-regular fa-copy"></i>Copy\n                </button>\n              </div>\n              <textarea id="russian-text" readonly class="flex-grow w-full bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm font-mono text-slate-800 focus:outline-none resize-none min-h-[140px]"></textarea>\n            </div>\n\n          </div>\n        </div>\n      </div>\n\n    </section>\n\n    <!-- TAB 2: GENERATE BRAILLE -->\n    <section id="panel-generate" class="hidden space-y-6">\n      <div class="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-4 max-w-3xl mx-auto">\n        <h2 class="text-lg font-bold text-slate-900 flex items-center gap-2">\n          <i class="fa-solid fa-pen-fancy text-blue-600"></i>Text-to-Braille Chart Generator\n        </h2>\n        <p class="text-sm text-slate-500">\n          Type English text below to synthesize a raised-dot Braille chart with standardized typography ($d_x=12\\text{px}$, line spacing $=45\\text{px}$).\n        </p>\n        <textarea id="gen-input" class="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm font-mono text-slate-800 focus:ring-2 focus:ring-blue-500 focus:outline-none min-h-[120px]" placeholder="Type text here...">hello world&#10;braille digitizer</textarea>\n        <button onclick="generateBraille()" class="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-xl transition shadow-md flex items-center justify-center gap-2">\n          <i class="fa-solid fa-wand-magic-sparkles"></i>Synthesize Braille Document\n        </button>\n\n        <div id="gen-result" class="hidden pt-4 border-t border-slate-100 space-y-4">\n          <div class="w-full bg-slate-100 rounded-xl p-4 flex items-center justify-center border border-slate-200">\n            <img id="gen-output-img" class="max-h-[400px] w-auto shadow-sm rounded-lg" alt="Generated Braille">\n          </div>\n          <div class="flex flex-col sm:flex-row justify-between items-center gap-3">\n            <button onclick="testGeneratedInRecognizer()" class="w-full sm:w-auto px-4 py-2 bg-blue-600 text-white text-xs font-semibold rounded-lg hover:bg-blue-700 transition flex items-center justify-center gap-2 shadow-sm">\n              <i class="fa-solid fa-microscope"></i>Recognize Generated Chart &rarr;\n            </button>\n            <a id="download-btn" download="braille_document.png" class="w-full sm:w-auto px-4 py-2 bg-slate-900 text-white text-xs font-semibold rounded-lg hover:bg-slate-800 transition flex items-center justify-center gap-2">\n              <i class="fa-solid fa-download"></i>Download PNG\n            </a>\n          </div>\n        </div>\n      </div>\n    </section>\n\n  </main>\n\n  <!-- Footer -->\n  <footer class="bg-white border-t border-slate-200 py-6 text-center text-xs text-slate-500">\n    <div class="max-w-7xl mx-auto px-4">\n      <p class="font-medium text-slate-700">Braille Digitizer OBR System &bull; Vercel Serverless Architecture</p>\n      <p class="mt-1">Powered by Whole-Page Lattice Grid Alignment, k-d Tree Spatial Pitch Estimation, and Unified English Braille (UEB).</p>\n    </div>\n  </footer>\n\n  <script>\n    function switchTab(tab) {\n      const pRecognize = document.getElementById(\'panel-recognize\');\n      const pGenerate = document.getElementById(\'panel-generate\');\n      const tRecognize = document.getElementById(\'tab-recognize\');\n      const tGenerate = document.getElementById(\'tab-generate\');\n\n      if (tab === \'recognize\') {\n        pRecognize.classList.remove(\'hidden\');\n        pGenerate.classList.add(\'hidden\');\n        tRecognize.className = "px-4 py-2 text-sm font-semibold rounded-lg bg-white shadow-sm text-blue-600 transition";\n        tGenerate.className = "px-4 py-2 text-sm font-semibold rounded-lg text-slate-600 hover:text-slate-900 transition";\n      } else {\n        pRecognize.classList.add(\'hidden\');\n        pGenerate.classList.remove(\'hidden\');\n        tGenerate.className = "px-4 py-2 text-sm font-semibold rounded-lg bg-white shadow-sm text-blue-600 transition";\n        tRecognize.className = "px-4 py-2 text-sm font-semibold rounded-lg text-slate-600 hover:text-slate-900 transition";\n      }\n    }\n\n    const dropZone = document.getElementById(\'drop-zone\');\n    [\'dragenter\', \'dragover\'].forEach(name => {\n      dropZone.addEventListener(name, (e) => { e.preventDefault(); dropZone.classList.add(\'dragover\'); });\n    });\n    [\'dragleave\', \'drop\'].forEach(name => {\n      dropZone.addEventListener(name, (e) => { e.preventDefault(); dropZone.classList.remove(\'dragover\'); });\n    });\n    dropZone.addEventListener(\'drop\', (e) => {\n      if (e.dataTransfer.files.length) {\n        processFile(e.dataTransfer.files[0]);\n      }\n    });\n\n    function handleFileSelect(event) {\n      if (event.target.files.length) {\n        processFile(event.target.files[0]);\n      }\n    }\n\n    async function processFile(file) {\n      const statusCard = document.getElementById(\'status-card\');\n      const statusText = document.getElementById(\'status-text\');\n      const statusSpinner = document.getElementById(\'status-spinner\');\n      const statsBadges = document.getElementById(\'stats-badges\');\n      const resultsContainer = document.getElementById(\'results-container\');\n\n      statusCard.classList.remove(\'hidden\');\n      statusSpinner.classList.remove(\'hidden\');\n      statsBadges.classList.add(\'hidden\');\n      statusText.innerText = "Analyzing raised dots and estimating lattice geometry...";\n\n      const formData = new FormData();\n      formData.append("file", file);\n\n      try {\n        const response = await fetch("/api/recognize", {\n          method: "POST",\n          body: formData\n        });\n\n        if (!response.ok) {\n          throw new Error("Recognition failed: " + response.statusText);\n        }\n\n        const data = await response.json();\n\n        // Update UI\n        statusSpinner.classList.add(\'hidden\');\n        statusText.innerText = `Successfully processed: ${data.dots_count} dots detected, ${data.cells_count} Braille cells decoded.`;\n        document.getElementById(\'badge-dots\').innerText = `${data.dots_count} Dots`;\n        document.getElementById(\'badge-cells\').innerText = `${data.cells_count} Cells`;\n        statsBadges.classList.remove(\'hidden\');\n\n        document.getElementById(\'overlay-img\').src = data.overlay_image;\n        document.getElementById(\'english-text\').value = data.english_text;\n        document.getElementById(\'russian-text\').value = data.russian_text;\n\n        resultsContainer.classList.remove(\'hidden\');\n      } catch (err) {\n        statusSpinner.classList.add(\'hidden\');\n        statusText.innerText = "Error: " + err.message;\n      }\n    }\n\n    async function generateBraille() {\n      const text = document.getElementById(\'gen-input\').value;\n      if (!text.trim()) return;\n\n      try {\n        const response = await fetch("/api/generate", {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify({ text: text })\n        });\n\n        const data = await response.json();\n        if (data.chart_image) {\n          const genResult = document.getElementById(\'gen-result\');\n          const genOutputImg = document.getElementById(\'gen-output-img\');\n          const downloadBtn = document.getElementById(\'download-btn\');\n\n          genOutputImg.src = data.chart_image;\n          downloadBtn.href = data.chart_image;\n          genResult.classList.remove(\'hidden\');\n        }\n      } catch (err) {\n        alert("Failed to synthesize Braille chart: " + err.message);\n      }\n    }\n\n    function copyText(elemId) {\n      const copyText = document.getElementById(elemId);\n      copyText.select();\n      navigator.clipboard.writeText(copyText.value);\n    }\n\n    async function loadSample(sampleText) {\n      const statusCard = document.getElementById(\'status-card\');\n      const statusText = document.getElementById(\'status-text\');\n      const statusSpinner = document.getElementById(\'status-spinner\');\n      statusCard.classList.remove(\'hidden\');\n      statusSpinner.classList.remove(\'hidden\');\n      statusText.innerText = "Synthesizing sample Braille document...";\n\n      try {\n        const genRes = await fetch("/api/generate", {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify({ text: sampleText })\n        });\n        const genData = await genRes.json();\n        if (genData.chart_image) {\n          const fetchImg = await fetch(genData.chart_image);\n          const blob = await fetchImg.blob();\n          const file = new File([blob], "sample.png", { type: "image/png" });\n          processFile(file);\n        }\n      } catch (err) {\n        statusSpinner.classList.add(\'hidden\');\n        statusText.innerText = "Sample load error: " + err.message;\n      }\n    }\n\n    async function testGeneratedInRecognizer() {\n      const imgEl = document.getElementById(\'gen-output-img\');\n      if (!imgEl.src) return;\n      const res = await fetch(imgEl.src);\n      const blob = await res.blob();\n      const file = new File([blob], "generated_braille.png", { type: "image/png" });\n      switchTab(\'recognize\');\n      processFile(file);\n    }\n  </script>\n</body>\n</html>\n'
